    wrapper_source = run_dir / "python-wrapper-orders.csv"
    wrapper_source.write_text(
        "id,label,amount\n1,alpha,8\n2,beta,15\n3,gamma,21\n",
        encoding="utf-8",
    )
    return {"local_source": local_source, "wrapper_source": wrapper_source}


