    fanout_stage = next(
        stage for stage in stages
        if stage["stage_id"] == "local_prepared_vortex_sql_jsonl_csv_fanout"
    )
    expected_rows = [
        {"id": 2, "label": "beta", "amount": 15},
        {"id": 3, "label": "gamma", "amount": 21},
